#!/usr/bin/env python3
"""Bake the simulated alert feed from the sealed demo audit fixtures."""

import argparse
import json
from dataclasses import asdict
from html import escape
from pathlib import Path
from urllib.parse import quote

from subpoena.alert_policy import AlertKey, alert_order, alerts_for_audit
from subpoena.models import AuditReport

DEFAULT_OUT = Path(__file__).resolve().parents[1] / "docs" / "demo"
DATA = DEFAULT_OUT / "data"

PAGE = """<!doctype html>
<!-- Generated by scripts/export_alerts_demo.py. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Alert feed | Subpoena</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; }
  body { margin: 0; background: #14161a; color: #e8e6df; font: 1rem/1.5 system-ui; }
  main { max-width: 54rem; margin: auto; padding: 1rem clamp(1rem, 4vw, 3rem) 3rem; }
  h1 { margin: .75rem 0; font-size: clamp(2rem, 7vw, 3.5rem); line-height: 1.1; }
  h2 { margin: .25rem 0; font-size: 1.125rem; }
  p { margin: 0 0 .5rem; color: #b2b7c3; }
  a { color: #82afff; text-underline-offset: .18em; }
  a:focus-visible { outline: 2px solid #82afff; outline-offset: 3px; }
  ol { list-style: none; display: grid; gap: .75rem; margin: 1.5rem 0; padding: 0; }
  li { padding: .875rem 1rem; border: 1px solid #373d4a; border-radius: .65rem;
       background: #1c1f26; min-width: 0; overflow-wrap: anywhere; }
  .severity { color: #ffc095; }
  .critical { color: #ff9a9a; }
  .links { display: flex; flex-wrap: wrap; gap: 0 1rem; }
  .links a { display: inline-flex; align-items: center; min-height: 44px; }
</style>
</head>
<body>
<main>
  <a href="hub.html#operations">Back to demo hub</a>
  <h1>Alert feed</h1>
  <p>Simulated feed. No notifications are sent.</p>
  <p>High and critical findings and mismatches from sealed demo audits, worst first.</p>
  <ol role="list">
@ALERTS@
  </ol>
  <a href="data-alerts/alerts.json">Download alert data (JSON)</a>
</main>
</body>
</html>
"""

CARD = """    <li>
      <strong class="severity {severity_class}">{severity}</strong> · {kind}
      <h2>{title}</h2>
      <p>{summary}</p>
      <div class="links">
        <a href="{audit_href}">Sealed audit (JSON)</a>
        <a href="{call_href}">Original call</a>
      </div>
    </li>"""


def export(out: Path = DEFAULT_OUT) -> None:
    scenarios = {}
    for scenario in json.loads((DATA / "scenarios.json").read_bytes()):
        run = json.loads((DATA / f"run-{scenario['id']}.json").read_bytes())
        scenarios[run["call"]["call_id"]] = scenario

    audits = [
        AuditReport.model_validate_json(path.read_bytes())
        for path in sorted(DATA.glob("audit-*.json"))
    ]
    seen: set[AlertKey] = set()
    alerts = []
    for audit in sorted(audits, key=lambda audit: (audit.created_at, audit.audit_id)):
        for alert in alerts_for_audit(audit, already_alerted=frozenset(seen)):
            alerts.append(alert)
            seen.add(alert.dedupe_key)

    records, cards = [], []
    for alert in sorted(alerts, key=alert_order):
        scenario = scenarios[alert.call_id]
        audit_href = f"data/audit-{quote(alert.audit_id, safe='')}.json"
        fragment = quote(scenario["id"], safe="-_.!~*'()")
        call_href = f"index.html#{fragment}"
        records.append(
            {
                **asdict(alert),
                "title": scenario["title"],
                "audit_href": audit_href,
                "call_href": call_href,
            }
        )
        cards.append(
            CARD.format(
                severity_class=alert.severity.lower(),
                severity=alert.severity,
                kind={"finding": "Open finding", "mismatch": "Mismatched verdict"}[alert.kind],
                title=escape(scenario["title"]),
                summary=escape(alert.summary),
                audit_href=escape(audit_href),
                call_href=escape(call_href),
            )
        )

    output_data = out / "data-alerts"
    output_data.mkdir(parents=True, exist_ok=True)
    (output_data / "alerts.json").write_text(json.dumps(records, indent=2) + "\n", encoding="utf-8")
    (out / "alerts.html").write_text(PAGE.replace("@ALERTS@", "\n".join(cards)), encoding="utf-8")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--out", type=Path, default=DEFAULT_OUT, help="Demo output directory")
    export(parser.parse_args().out)
